import React, { useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";

export default function Lobby() {
  const [searchParams] = useSearchParams();
  const room = searchParams.get("room");
  const navigate = useNavigate();

  useEffect(() => {
    if (!room) {
      alert("No room provided — redirecting.");
      navigate("/join");
    }
  }, [room, navigate]);

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0f0f10 0%, #1a1c1f 100%)",
        padding: "40px 20px",
        display: "flex",
        justifyContent: "center",
        alignItems: "flex-start",
        fontFamily: "Inter, sans-serif",
      }}
    >
      <div
        style={{
          width: "900px",
          maxWidth: "95%",
          background: "rgba(255,255,255,0.06)",
          borderRadius: "22px",
          padding: "40px",
          border: "1px solid rgba(255,255,255,0.08)",
          boxShadow: "0 25px 60px rgba(0,0,0,0.45)",
          backdropFilter: "blur(18px)",
          animation: "fadeIn 0.7s ease",
          color: "#fff",
        }}
      >
        {/* HEADER */}
        <h1
          style={{
            fontSize: "36px",
            fontWeight: 800,
            textAlign: "center",
            marginBottom: "10px",
            background: "linear-gradient(90deg, #4facfe, #00f2fe)",
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
          }}
        >
          Room Lobby
        </h1>

        <h2
          style={{
            fontSize: "22px",
            textAlign: "center",
            opacity: 0.85,
            marginBottom: "30px",
          }}
        >
          Room Code:{" "}
          <span style={{ color: "#4facfe", fontWeight: 700 }}>{room}</span>
        </h2>

        <p
          style={{
            textAlign: "center",
            fontSize: "15px",
            color: "#c5c5c5",
            marginBottom: "40px",
          }}
        >
          Choose how you want to collaborate — real-time editing or AI-powered
          code explanations.
        </p>

        {/* GRID SECTION */}
        <div
          style={{
            display: "grid",
            gap: "30px",
            gridTemplateColumns: "1fr 1fr",
          }}
        >
          {/* ⭐ CODE EXPLAINER CARD */}
          <LobbyCard
            title="🔍 Code Explainer"
            description="Let Gemini analyze, explain and visualize your code instantly."
            buttonText="Open Code Explainer"
            colors={{
              button: "linear-gradient(135deg,#4facfe,#00f2fe)",
              border: "rgba(0,242,254,0.4)",
            }}
            onClick={() => navigate(`/explainer?room=${room}`)}
          />

          {/* ⭐ LIVE COLLAB CARD */}
          <LobbyCard
            title="👥 Live Collaboration"
            description="Edit together in real-time with synchronized text and comments."
            buttonText="Open Collaboration Mode"
            colors={{
              button: "linear-gradient(135deg,#ff9966,#ff5e62)",
              border: "rgba(255,152,99,0.4)",
            }}
            onClick={() => navigate(`/collaboration?room=${room}`)}
          />
        </div>

        {/* BACK BUTTON */}
        <div style={{ textAlign: "center", marginTop: "45px" }}>
          <button
            onClick={() => navigate("/join")}
            style={{
              padding: "12px 24px",
              borderRadius: "10px",
              background: "rgba(255,255,255,0.1)",
              color: "#eee",
              border: "1px solid rgba(255,255,255,0.15)",
              cursor: "pointer",
              fontSize: "15px",
              transition: "0.3s",
            }}
            onMouseOver={(e) => (e.target.style.opacity = "0.6")}
            onMouseOut={(e) => (e.target.style.opacity = "1")}
          >
            ⬅ Back to Join Page
          </button>
        </div>
      </div>
    </div>
  );
}

/* CARD COMPONENT */
function LobbyCard({ title, description, buttonText, colors, onClick }) {
  return (
    <div
      style={{
        padding: "30px",
        background: "rgba(255,255,255,0.05)",
        borderRadius: "18px",
        border: `1px solid ${colors.border}`,
        transition: "0.25s ease",
        cursor: "default",
      }}
      onMouseOver={(e) => {
        e.currentTarget.style.transform = "translateY(-6px)";
        e.currentTarget.style.boxShadow =
          "0 18px 40px rgba(0,0,0,0.45)";
      }}
      onMouseOut={(e) => {
        e.currentTarget.style.transform = "translateY(0)";
        e.currentTarget.style.boxShadow = "none";
      }}
    >
      <h3 style={{ fontSize: "22px", marginBottom: "10px" }}>{title}</h3>
      <p style={{ color: "#c7c7c7", marginBottom: "25px", lineHeight: "1.5" }}>
        {description}
      </p>

      <button
        onClick={onClick}
        style={{
          width: "100%",
          padding: "14px",
          borderRadius: "12px",
          background: colors.button,
          border: "none",
          fontSize: "16px",
          fontWeight: 700,
          cursor: "pointer",
          color: "#000",
          transition: "0.25s ease",
        }}
        onMouseOver={(e) => {
          e.target.style.filter = "brightness(1.1)";
        }}
        onMouseOut={(e) => {
          e.target.style.filter = "brightness(1)";
        }}
      >
        {buttonText}
      </button>
    </div>
  );
}
